(()=>{document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("menu-toggle"),e=document.getElementById("navbarNav"),s=document.getElementById("show-button"),o=document.getElementById("hide-button"),t=()=>{const t=e.classList.contains("show");e.classList.toggle("show"),s.classList.toggle("d-none",!t),o.classList.toggle("d-none",t)};n.addEventListener("click",t),e.querySelectorAll(".nav-link, .dropdown-item").forEach(n=>{n.addEventListener("click",()=>{window.innerWidth<992&&e.classList.contains("show")&&t()})})})})()